import {renderSkillEntry} from './skill-discovery-ui.js?v=20261026-15.0';
import {renderContextShortcuts} from './context-shortcuts.js?v=20261026-15.0';
import {savedExperts} from './expert-library.js?v=20261026-15.0';
import {esc,icon,uid,newTask} from './core.js?v=20261026-15.0';
import {renderViewer,applyAnnotations} from './viewer.js?v=20261026-15.0';
import {SCENARIOS,ROLES,PHASES,initOffice,seedOfficeTask,detectScenario,startRun,advance,pause,recover,repair,decide,execute,updateStep,reorder,addStep,removeStep,report,event,syncArtifacts,createApproval,invalidateApproval} from './office-model.js?v=20261026-15.0';
const E=esc;
const B=(label,action,attrs='',kind='')=>`<button class="btn ${kind}" data-action="office:${action}" ${attrs}>${label}</button>`;
const tag=(c,label='新增')=>c.state.office.reviewMarks?`<span class="of-change">${label}</span>`:'';
const pill=(text,kind='')=>`<span class="of-pill ${kind}">${E(text)}</span>`;
const taskBy=(c,id)=>c.state.tasks.find(t=>t.id===id);
const current=c=>c.currentTask();
const tasks=c=>c.state.tasks.filter(t=>t.office);
const agentBy=(c,id)=>c.state.office.agents.find(a=>a.id===id);
const clock=t=>new Date(t).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
function personalSignals(c){const o=c.state.office;if(o.level===0||o.quiet)return [];const list=[];for(const id of o.follows){const t=taskBy(c,id);if(!t?.office)continue;const baseline=o.followVersions?.[id]||{};const changed=t.files.filter(f=>f.version>(baseline[f.id]||0));if(changed.length)list.push({id:'change:'+id+':'+changed.map(f=>f.version).join('-'),task:id,title:'关注的成果有了新版本',why:changed.map(f=>`${f.name} v${f.version}`).join('、'),text:'已整理变化入口，回到原任务核对，不创建重复成果。'});}for(const t of tasks(c).filter(t=>['paused','blocked','review','ready','approved'].includes(t.office.phase)).slice(0,3))list.push({id:'state:'+t.id+':'+t.office.phase,task:t.id,title:t.office.phase==='blocked'?'这件工作需要恢复连接':t.office.phase==='review'?'有一版成果需要重新验收':'有一件工作等你推进',why:`${t.title} · ${PHASES[t.office.phase]}`,text:'建议来自当前任务状态；处理后会自动更新。'});return list.filter(x=>!o.dismissed.includes(x.id));}
export function renderOfficeDock(c){const signals=personalSignals(c),n=signals.length;return `<button class="per-dock ${c.ui.officePersonalOpen?'is-open':''}" data-action="per:open" aria-expanded="${!!c.ui.officePersonalOpen}" aria-label="打开小悠主动协助"><span class="per-avatar" aria-hidden="true">${icon('bell',20)}</span><span><strong>主动协助</strong><small>${c.state.office.quiet?'主动提醒已暂停':n?`${n} 件事值得看看`:'有事一起想，进展一起跟'}</small></span>${n?`<b class="per-count">${n}</b>`:icon('chevron',15)}</button>`;}
function proactiveSuggestions(c){const o=c.state.office;if(o.level===0)return '<p class="of-muted">当前只响应交办。你可以在“主动协助”选择关注与准备范围。</p>';if(o.quiet)return '<p class="of-muted">主动提醒已暂停；已有工作照常保留。</p>';const signals=personalSignals(c);return signals.map(s=>`<div class="of-suggestion"><small>${icon('eye',14)} 为什么现在：${E(s.why)}</small><h3>${E(s.title)}</h3><p>${E(s.text)}</p><div>${B('回到原工作','source-task',`data-id="${s.task}"`,'primary small')}${B('这次不用','dismiss-signal',`data-id="${s.id}"`,'ghost small')}</div></div>`).join('')+(!o.dismissed.includes('prepare')?`<div class="of-suggestion"><small>${icon('book',14)} 仅使用明确选择的示例资料</small><h3>试试让小悠先准备，再由你决定</h3><p>自动完成允许的只读步骤，外部写回仍停在确认前。</p><div>${B('先帮我准备','prepare','','primary small')}${B('这次不用','dismiss','','ghost small')}</div></div>`:'');}
function mark(c,title,body){return c.state.office.reviewMarks?`<div class="of-review-note"><b>${title}</b><span>${body}</span></div>`:'';}
export function renderOfficeBar(c){if(c.ui.route==='home'||c.ui.route.startsWith('agent/')||c.ui.route.startsWith('chat/')||c.ui.route.startsWith('local-agent/')||['task-center','schedules'].includes(c.ui.route))return '';const o=initOffice(c.state);return `<div class="of-reviewbar"><span>${icon('shield',13)} 本地交互演示 · 业务数据与外部操作均为模拟</span><div>${B(o.reviewMarks?'隐藏改动标记':'查看本次改动','marks','','ghost small')}${B('原版对照','compare','','ghost small')}${B('重置本轮体验','reset','','ghost small')}</div></div>`;}
function taskRow(c,t){const o=t.office;return `<button class="of-task-row" data-action="app:go" data-route="chat/${t.id}"><span class="of-task-symbol">${icon(SCENARIOS[o.scenario]?.icon||'file',19)}</span><span class="of-task-text"><strong>${E(t.title)}</strong><small>${E(agentBy(c,o.agentId)?.name||'小悠')} · ${E(c.state.projects.find(p=>p.id===t.project)?.name||'个人工作')} · ${o.steps.filter(s=>s.status==='complete').length}/${o.steps.length} 步</small></span>${pill(PHASES[o.phase],o.phase==='complete'?'green':['blocked','review','rejected'].includes(o.phase)?'orange':'blue')}${icon('chevron',15)}</button>`;}
function scenarioButtons(c){return `<div class="of-section-heading"><h3>从一件具体工作开始</h3><span>四条可连续体验的样例流程</span></div><div class="of-scenarios">${Object.entries(SCENARIOS).map(([id,s])=>`<button data-action="office:scenario" data-id="${id}"><span>${icon(s.icon,20)}</span><strong>${s.name}</strong><small>${{review:'资料 → 分析 → 验收 → 确认交付',reconcile:'连接失败 → 保留成果 → 恢复',proposal:'项目资料 → 同事补充 → 任务交接',builder:'工作说明 → 面板试用 → 候选发布'}[id]}</small>${icon('arrow',16)}</button>`).join('')}</div>`;}
function startComposer(c,{agentId='',projectId=''}={}){const refs=c.state.homeContext||[];return `${renderContextShortcuts({target:'home',inputId:'office-prompt'})}<form class="of-start" data-form="office:start"><input type="hidden" name="agent" value="${E(agentId)}"><input type="hidden" name="project" value="${E(projectId)}"><textarea id="office-prompt" name="prompt" data-live="office:home" rows="3" placeholder="交给小悠：目标是什么，希望拿到什么成果？" aria-label="交办工作目标">${E(c.state.homeDraft||'')}</textarea>${refs.length?`<div class="of-chips">${refs.map((r,i)=>`<button type="button" data-action="chat:view-context" data-index="${i}">${icon('file',13)}${E(r.name)}</button>`).join('')}</div>`:''}<div class="of-start-tools"><button type="button" class="btn ghost small" data-action="chat:context-menu">${icon('plus',16)}资料与能力</button><span>${icon('shield',14)} 敏感操作由我确认</span><button class="btn primary" type="submit">交给${agentId?E(agentBy(c,agentId)?.name||'小悠'):'小悠'} ${icon('arrow',16)}</button></div></form>`;}
function home(c){const work=[...tasks(c)].filter(t=>!['complete','rejected','cancelled'].includes(t.office.phase)).sort((a,b)=>b.createdAt-a.createdAt),pending=work.filter(t=>['ready','approved','blocked','review'].includes(t.office.phase)),attention=c.ui.homeWorkFilter==='attention',shown=(attention?pending:work).slice(0,3);return `<main class="of-page xy-home" data-screen-label="小悠工作首页"><section class="xy-home-module xy-create" aria-label="交办工作"><header class="xy-home-header"><img src="./assets/xiaoyou.png" alt="小悠海豚"><h1>今天，想一起完成什么？</h1></header>${startComposer(c)}<div class="xy-home-options">${B(icon('bolt',14)+'工作方法','home-methods','','ghost small')}${B(icon('play',14)+'工作示例','home-examples','','ghost small')}<span>本地交互演示</span></div></section><section class="xy-home-module xy-continue" aria-label="继续工作"><header><h2>继续工作</h2><nav aria-label="首页工作筛选">${B('最近','home-filter','data-id="recent" aria-pressed="'+!attention+'"',!attention?'selected':'')}${B('待我处理'+(pending.length?' '+pending.length:''),'home-filter','data-id="attention" aria-pressed="'+attention+'"',attention?'selected':'')}</nav><button class="xy-all-work" data-action="app:go" data-route="task-center">全部任务 ${icon('arrow',13)}</button></header><div class="xy-home-work-list">${shown.length?shown.map(t=>taskRow(c,t)).join(''):`<p class="xy-home-empty">${attention?'暂时没有需要你处理的事项。':'还没有进行中的工作。把想做的事交给小悠吧。'}</p>`}</div></section></main>`;}

function agentCard(c,a){return `<button class="of-agent-card" data-action="app:go" data-route="agent/${a.id}"><span class="of-agent-icon">${icon(a.icon||'expert',22)}</span><div><strong>${E(a.name)}</strong><p>${E(a.description)}</p><small>${E(a.source)} · ${E(a.version)} · ${tasks(c).filter(t=>t.office.agentId===a.id).length} 项工作</small></div>${icon('chevron',15)}</button>`;}
function agents(c){return `<main class="of-page"><div class="of-page-heading"><div><div class="of-eyebrow">持续工作的业务伙伴</div><h1>我的智能体 ${tag(c)}</h1><p>召唤后固定在左侧，持续对话，按需展开工作面板。</p></div><div>${B('发现专家','discover','','small')}<button class="btn" data-action="catalog:new-expert">创建专家</button></div></div>${mark(c,'召唤后固定到左侧，回到同一段对话','点击左侧 Agent 继续聊；具体工作的计划、小队、进度与成果在右侧。')}<div class="of-agent-grid wide">${c.state.office.agents.map(a=>agentCard(c,a)).join('')}</div><div class="of-section-heading"><h3>最近推进的工作</h3></div>${tasks(c).map(t=>taskRow(c,t)).join('')||'<div class="of-empty-inline">从左侧进入 Agent，先聊聊要做的事。</div>'}</main>`;}
function agentWorkspace(c,id){const a=agentBy(c,id);if(!a)return agents(c);const work=tasks(c).filter(t=>t.office.agentId===id);return `<main class="of-page"><div class="of-page-heading"><div><div class="of-eyebrow">${E(a.source)} · 已发布 ${E(a.version)} · 示例连接就绪</div><h1>${icon(a.icon,27)} ${E(a.name)} ${tag(c,'持续工作区')}</h1><p>${E(a.description)}。这里保留你的工作，不因再次进入而新建对话。</p></div>${B(a.pinned?'取消固定':'固定到我的智能体','pin',`data-id="${id}"`,'small')}</div><div class="of-workspace-summary"><span>${icon('user',17)} 维护团队：示例业务团队</span><span>${icon('book',17)} 本工作区资料与记忆独立</span>${B('查看工作说明','agent-detail',`data-id="${id}"`,'ghost small')}</div>${startComposer(c,{agentId:id})}<div class="of-section-heading"><h3>继续工作</h3><span>${work.length} 项，保留原任务和版本</span></div>${work.map(t=>taskRow(c,t)).join('')||'<div class="of-empty-inline">还没有工作。输入目标即可生成计划，无需重复召唤专家。</div>'}${scenarioButtons(c)}</main>`;}
function project(c,id){const p=c.state.projects.find(p=>p.id===id);if(!p)return home(c);return `<main class="of-page"><div class="of-page-heading"><div><div class="of-eyebrow">项目工作区</div><h1>${E(p.name)} ${tag(c,'上下文演进')}</h1><p>${E(p.description||'项目内的资料、决定与工作保持在一起。')}</p></div><button class="btn" data-action="app:edit-project" data-id="${id}">管理项目</button></div><div class="of-context-shelf"><div>${icon('book',21)}<strong>项目资料</strong><p>流程图 v2、访谈摘录与样例数据</p>${B('核对引用范围','project-sources',`data-project="${id}"`,'ghost small')}</div><div>${icon('checkCircle',21)}<strong>已确认决定</strong><p>业务写回保留人工确认</p><small>示例决定 · 林沐 · 2026-10-20</small></div><div>${icon('expert',21)}<strong>团队协作</strong><p>同一任务接续，资料权限重新核对</p>${B('查看团队 Agent','team','','ghost small')}</div></div>${startComposer(c,{projectId:id})}<div class="of-section-heading"><h3>项目工作</h3></div>${c.state.tasks.filter(t=>t.project===id).map(t=>t.office?taskRow(c,t):`<button class="of-task-row" data-action="app:go" data-route="chat/${t.id}">${icon('history',20)}<strong>${E(t.title)}</strong>${pill('原有历史')}<span>打开原成果</span></button>`).join('')||'<div class="of-empty-inline">这个项目还没有任务。</div>'}</main>`;}
function stepStatus(s,o){if(s.status==='complete')return '已完成';if(s.status==='failed')return '需处理';if(s.sensitive)return o.phase==='complete'?'已交付':o.phase==='rejected'?'已停止':'需人工确认';if(o.phase==='running'&&s.status==='pending'&&s.deps.every(id=>o.steps.find(x=>x.id===id)?.status==='complete'))return '处理中';return '待开始';}
function board(c,t){const o=t.office;return `<div class="of-board-intro"><div><h3>计划与分工 ${tag(c,'本次运行小队')}</h3><p>主 Agent 按目标组队，临时角色仅在本次任务中运行。</p></div><div class="of-inline-actions">${B('增补专家步骤','add-step','','small')}${pill(`计划 v${o.planVersion}`,'blue')}</div></div><div class="of-lead"><span class="of-lead-symbol">${icon('sparkles',20)}</span><div><strong>${E(o.hostName||'小悠')} · Lead</strong><small>拆解目标 · 创建临时子 Agent · 汇总交付</small></div>${pill('主 Agent 主持')}</div>${o.consultations?.length?`<div class="ex-consulted-strip"><span>会话中受邀</span>${[...new Map(o.consultations.map(x=>[x.expert.id,x.expert])).values()].map(x=>`<button data-action="expert:detail" data-id="${E(x.publishId)}">${E(x.name)} <small>${E(x.version)}</small></button>`).join('')}<small>意见由当前主持 Agent 汇总</small></div>`:''}<div class="of-plan-board" aria-label="可编辑小队计划">${o.steps.map((s,i)=>`<article class="of-step ${s.status} ${s.sensitive?'sensitive':''}" draggable="${o.phase!=='running'}" data-office-step="${s.id}" data-task="${t.id}"><button class="of-step-main" data-action="office:step" data-id="${s.id}"><span class="of-step-index of-step-grip" data-office-drag-handle title="拖拽调整步骤顺序">${s.status==='complete'?icon('check',16):String(i+1).padStart(2,'0')}</span><span class="of-step-info"><strong>${E(s.title)}</strong><small>${E(s.role)} <span class="ex-role-kind">${s.expertId?'企业专家':s.agentType==='lead'||['lead','deliver'].includes(s.id)?'主持':s.id==='check'?'独立验收':'本次临时'}</span></small><em>${E(s.output)}</em></span><span class="of-step-state">${s.sensitive?icon('shield',13):''}${stepStatus(s,o)}</span></button><div class="of-step-footer"><span>${s.deps.length?'依赖 '+s.deps.map(id=>E(o.steps.find(x=>x.id===id)?.title||id)).join('、'):'可独立开始 · 按需并行'}</span><div>${B('↑','move',`data-id="${s.id}" data-direction="-1" aria-label="上移${E(s.title)}"`,'ghost small')}${B('↓','move',`data-id="${s.id}" data-direction="1" aria-label="下移${E(s.title)}"`,'ghost small')}</div></div></article>`).join('')}</div>`;}
function rubric(c,t){const o=t.office;return `<section class="of-quality"><div class="of-section-heading"><h3>独立验收 ${tag(c)}</h3>${pill(o.quality==='passed'?'已通过':o.quality==='failed'?'未通过':'待检查',o.quality==='passed'?'green':'orange')}</div>${o.rubric.length?o.rubric.map(r=>`<div class="of-check-row">${icon(r.pass?'checkCircle':'alert',18)}<div><strong>${E(r.name)}</strong><p>${E(r.evidence)}</p></div>${pill(r.pass?'通过':'返工',r.pass?'green':'orange')}</div>`).join(''):'<p class="of-muted">按目标覆盖、口径一致、来源与操作边界逐项检查，保留证据。</p>'}${o.selfCheck?`<div class="of-selfcheck">${icon('shield',18)}<div><strong>Lead 自核完成</strong><p>${o.selfCheck.items.join(' · ')}</p><small>计划 v${o.selfCheck.plan} · 报告 v${o.selfCheck.reportVersion}</small></div></div>`:''}</section>`;}
function approvalCard(c,t){const o=t.office,a=o.approval;return `<section class="of-approval"><div class="of-section-heading"><h3>${icon('shield',18)} 操作确认 ${tag(c)}</h3>${pill(a?({pending:'待我确认',approved:'已批准',rejected:'已拒绝',invalid:'内容变化 · 已失效',executed:'已执行'}[a.status]):'验收通过后生成','orange')}</div>${a?`<strong>${E(a.action)}</strong><p>${E(a.target)}</p><div class="of-approval-meta"><span>执行身份：我 · ${E(agentBy(c,o.agentId)?.name||'小悠')}</span><span>${E(a.scope)}</span><span>绑定计划 v${a.planVersion} · ${a.versions.map(f=>E(f.name)+' v'+f.version).join('、')}</span></div>${a.status==='pending'?`<div class="of-inline-actions">${B('查看内容并确认','approval',`data-id="${a.id}"`,'primary')}${B('拒绝','reject',`data-id="${a.id}"`,'small')}</div>`:a.status==='approved'?`<div class="of-inline-actions">${B('执行已批准操作','execute',`data-id="${a.id}"`,'primary')}${B('修改报告，验证重新确认','edit-report','','small')}</div>`:a.status==='rejected'?`${B('修改交付对象后重新提交','revise-delivery','','small')}`:''}${a.reason?`<p class="of-warning">${E(a.reason)}</p>`:''}`:'<p class="of-muted">采用计划只启动允许的步骤。写回、发送与发布单独确认。</p>'}${o.receipts.map(r=>`<div class="of-receipt">${icon('checkCircle',20)}<div><strong>${E(r.status)}</strong><p>${E(r.action)} → ${E(r.target)}</p><small>${E(r.id)} · ${clock(r.at)} · ${r.versions.map(f=>E(f.name)+' v'+f.version).join('、')}</small></div></div>`).join('')}</section>`;}
function execution(c,t){const o=t.office;return `<div class="of-board-intro"><div><h3>执行现场 ${tag(c,'环境式交互')}</h3><p>步骤、角色、成果和操作记录属于同一任务。</p></div>${B('查看计划','view','data-view="plan"','small')}</div>${o.phase==='blocked'?`<div class="of-state-banner warning">${icon('alert',24)}<div><strong>数据连接中断，已有研究成果已保留</strong><p>恢复后仅继续数据核对与受影响步骤。</p></div>${B('恢复连接并继续','recover','','primary')}</div>`:''}${o.phase==='review'?`<div class="of-state-banner warning">${icon('alert',24)}<div><strong>${o.quality==='failed'?'独立校验发现摘要与表格不一致':'成果版本已更新，需要重新验收'}</strong><p>不交付未通过的版本，其他有效成果保留。</p></div>${B(o.quality==='failed'?'修正并重新验收':'按最新版本验收','repair','','primary')}</div>`:''}${o.phase==='rejected'?`<div class="of-state-banner warning">${icon('shield',24)}<div><strong>你已拒绝，交付动作已停止</strong><p>没有发生业务写回，修改方案后可重新提交。</p></div>${B('修改交付方案','revise-delivery','','small')}</div>`:''}<div class="of-run-steps">${o.steps.map(s=>`<button data-action="${['check','lead','deliver'].includes(s.id)?'office:step':'cv:step'}" data-task="${t.id}" data-id="${s.id}" class="${s.status}"><span>${icon(s.status==='complete'?'checkCircle':s.status==='failed'?'alert':s.sensitive?'shield':'clock',18)}</span><div><strong>${E(s.title)}</strong><small>${E(s.role)} · ${E(s.output)}</small></div>${pill(stepStatus(s,o),s.status==='complete'?'green':s.status==='failed'?'orange':'')}</button>`).join('')}</div><div class="of-section-heading"><h3>最近发生</h3>${B('完整回放','view','data-view="replay"','ghost small')}</div><div class="of-mini-events">${o.events.slice(-3).reverse().map(e=>`<div><time>${clock(e.at)}</time><strong>${E(e.title)}</strong><p>${E(e.detail)}</p></div>`).join('')}</div>`;}
function replay(c,t){const o=t.office;return `<div class="of-board-intro"><div><h3>运行回放 ${tag(c)}</h3><p>记录计划、角色、版本、验收和人的决定；回放只读。</p></div>${pill(`${o.events.length} 条记录`)}</div><div class="of-timeline">${o.events.slice().reverse().map(e=>`<article><span>${icon(({approval:'shield',plan:'expert',check:'checkCircle',version:'edit',failure:'alert',delivery:'send'}[e.kind])||'clock',17)}</span><div><time>${clock(e.at)} · 计划 v${e.planVersion}</time><strong>${E(e.title)}</strong><p>${E(e.detail)}</p></div></article>`).join('')}</div>${o.planHistory.length?`<details class="of-history"><summary>查看 ${o.planHistory.length} 个旧计划版本</summary>${o.planHistory.map(p=>`<p>v${p.version} · ${p.steps.map(s=>E(s.title)+'（'+E(s.role)+'）').join(' → ')}</p>`).join('')}</details>`:''}`;}
function worksite(c,t){const o=t.office;syncArtifacts(t);const active=o.view||'plan',remaining=o.steps.filter(s=>s.status==='complete').length;return `<main class="of-worksite" data-screen-label="任务执行现场" data-office-view="${active}"><header class="of-task-header"><div><div class="of-eyebrow">${E(agentBy(c,o.agentId)?.name||'小悠')} / ${E(c.state.projects.find(p=>p.id===t.project)?.name||'个人工作')} · ${remaining}/${o.steps.length} 步 · 负责人：${E(o.owner)}</div><h1>${E(t.title)} ${pill(PHASES[o.phase],o.phase==='complete'?'green':'blue')}</h1></div><div class="of-inline-actions">${o.phase==='running'?B(icon('pause',14)+' 暂停','pause','','small'):o.phase==='paused'?B('继续','start','','primary'):''}${o.scenario==='builder'?B('评测样例','eval','','small'):''}${B('上下文','context','','small')}${B('更多','task-menu','','small')}</div></header><div class="of-goal-line"><span>${icon('target',16)}${E(t.prompt)}</span>${B('调整交付','revise-delivery','','ghost small')}</div><nav class="of-stage-tabs" aria-label="任务现场视图">${[['plan','计划与小队','expert'],['execute','执行现场','activity'],['approval','确认与验收','shield'],['replay','运行回放','history']].map(([id,n,i])=>`<button class="${active===id?'active':''}" data-action="office:view" data-view="${id}">${icon(i,16)}${n}${id==='approval'&&o.approval?.status==='pending'?'<i></i>':''}</button>`).join('')}<span>同一任务 · 持续接续</span></nav><div class="of-task-body ${t.viewer?.open?'with-viewer':''}"><section class="of-control-column"><div class="of-work-scroll">${active==='plan'?board(c,t):active==='replay'?replay(c,t):active==='approval'?rubric(c,t)+approvalCard(c,t):execution(c,t)}${active==='plan'?`<div class="of-plan-start"><p>允许的步骤在同一现场执行；敏感操作单独请你确认。</p>${o.phase==='plan'||o.phase==='paused'?B('采用计划并开始','start','','primary'):B('前往执行现场','view','data-view="execute"','primary')}</div>`:''}${o.phase==='complete'?`<div class="of-finish-actions"><strong>${icon('checkCircle',20)}工作已交付，方法可以继续复用</strong><div>${B('设为持续助理','automation','','small')}${B('交接给同事','handoff','','small')}${o.scenario==='builder'?B('同事试用与反馈','builder-feedback','','small'):''}</div></div>`:''}</div><div class="of-task-composer">${t.annotations?.length?`<div class="of-annotation-count">${t.annotations.length} 条元素批注待提交</div>`:''}<form data-form="office:message"><textarea id="office-task-input" name="message" data-live="office:task" rows="2" aria-label="补充要求或提交批注" placeholder="补充要求、回答问题，或发送右侧的元素批注…">${E(o.draft||'')}</textarea><button class="btn primary" type="submit" aria-label="提交补充要求">${icon('send',17)}</button></form></div></section>${t.viewer?.open?renderViewer(c,t):`<aside class="of-result-aside"><div class="of-section-heading"><h3>成果与工作资料</h3>${tag(c,'沿用并增强')}</div>${t.files.length?t.files.map(f=>`<button class="of-file" data-action="viewer:open" data-task="${t.id}" data-id="${f.id}">${icon(f.type==='sheet'?'chart':f.type==='html'?'panel':'file',22)}<div><strong>${E(f.name)}</strong><small>v${f.version} · ${o.quality==='passed'?'已验收':'过程草稿'} · 点击预览与修改</small></div>${icon('chevron',15)}</button>`).join(''):'<div class="of-empty-artifact">'+icon('panel',35)+'<strong>成果在执行过程中逐步出现</strong><p>文档、数据表和面板都留在这个现场。</p></div>'}<section class="of-source-list"><h3>本次资料 ${o.sources.length}</h3>${o.sources.map((s,i)=>B(icon('book',14)+' '+E(s.name),'source',`data-index="${i}"`,'ghost small')).join('')}</section><div class="of-boundary">${icon('shield',17)}<p>研究、核对与草稿可先做。<br>业务写回、发送和发布由你确认。</p></div>${active!=='approval'&&['ready','approved','rejected','complete'].includes(o.phase)?approvalCard(c,t):''}</aside>`}</div><footer class="of-simulation-controls"><span>体验控制 · 本地模拟</span>${B('推进一步','advance','',o.phase==='running'?'small':'ghost small')}${B('模拟连接失败','fail','','ghost small')}${B('修改报告','edit-report','','ghost small')}${B('同事补充','colleague','','ghost small')}</footer></main>`;}
export function renderOffice(c){initOffice(c.state);const r=c.ui.route;if(r==='home')return home(c);if(r==='experts'||r==='agents')return agents(c);if(r.startsWith('agent/'))return agentWorkspace(c,r.slice(6));if(r.startsWith('project/'))return project(c,r.slice(8));if(r.startsWith('chat/')){const t=current(c);if(t?.office)return worksite(c,t);}if(r==='templates')return home(c);return '';}
export function renderOfficePersonal(c){if(!c.ui.officePersonalOpen)return '';const o=c.state.office,work=tasks(c),waiting=work.filter(t=>['ready','approved','blocked','review'].includes(t.office.phase));const tab=c.ui.officePersonalTab||'overview';return `<aside class="of-personal-panel" aria-label="小悠个人智能体"><header><img src="./assets/xiaoyou.png" alt=""><div><h2>小悠一直在</h2><p>跨项目看进展，回到原现场推进</p></div>${B(icon('close',19),'close-personal','aria-label="关闭小悠个人面板"','ghost small')}</header><nav class="of-personal-tabs">${[['overview','工作概览'],['initiative','主动协助'],['memory','长期记忆']].map(([id,n])=>B(n,'personal-tab',`data-id="${id}"`,tab===id?'primary small':'ghost small')).join('')}</nav><div class="of-personal-scroll">${mark(c,'新增：个人工作入口','沿用主动建议与记忆，补充跨项目工作概览、分级约定和可返回的执行现场。')}${tab==='overview'?`<div class="of-section-heading"><h3>现在值得关注</h3>${pill(waiting.length+' 件')}</div>${waiting.map(t=>taskRow(c,t)).join('')||'<p class="of-muted">暂时没有阻塞事项。开始一个样例，小悠会根据真实演示状态更新这里。</p>'}<div class="of-personal-summary"><h3>跨项目工作汇总</h3><p>${work.length?`你有 ${work.length} 项演示工作，${work.filter(t=>t.office.phase==='complete').length} 项已交付，${waiting.length} 项需要处理。`:'这里汇总获准任务的进展，不把所有项目正文混在一起。'}</p>${work.map(t=>`<button data-action="office:source-task" data-id="${t.id}"><strong>${E(t.title)}</strong><span>${E(PHASES[t.office.phase])} ${icon('arrow',14)}</span></button>`).join('')}</div>${proactiveSuggestions(c)}<div class="of-section-heading"><h3>持续关注</h3>${B('关注当前任务','follow','','ghost small')}</div>${o.follows.map(id=>taskBy(c,id)).filter(Boolean).map(t=>`<div class="of-follow"><strong>${E(t.title)}</strong><small>仅关注此任务与成果版本 · ${E(PHASES[t.office.phase])}</small>${B('取消关注','unfollow',`data-id="${t.id}"`,'ghost small')}</div>`).join('')||'<p class="of-muted">只跟进你明确选择的工作。</p>'}`:tab==='initiative'?`<h3>主动到哪一步，由你决定 ${tag(c)}</h3><p class="of-muted">按工作约定设置。敏感操作人审、资料权限始终生效。</p>${[['我叫你时再做','只响应交办，不主动关注'],['有变化提醒我','关注指定对象，给出变化依据'],['先帮我准备','在约定范围内只读查询、形成草稿'],['按约定推进','明确白名单、预算和期限，敏感操作仍人审']].map(([n,d],i)=>`<button class="of-level ${o.level===i?'selected':''}" data-action="office:level" data-level="${i}"><b>L${i}</b><div><strong>${n}</strong><small>${d}</small></div>${icon(o.level===i?'checkCircle':'shield',18)}</button>`).join('')}<div class="of-agreement"><h3>当前工作约定</h3><p>资料范围：我主动选择的任务和示例来源</p><p>可自动做：${o.level===0?'只响应当前交办':o.level===1?'变化摘要与应用内提醒':o.level===2?'只读准备、计划与草稿':'白名单内的本地整理与归档'}</p><p>始终请我确认：外部发送、业务写回、发布、权限扩大</p>${B(o.quiet?'恢复主动提醒':'暂停主动提醒','quiet','','small')}</div><div class="of-boundary">${icon('shield',20)}<p>主动性 × 操作风险 × 连接权限独立判断。提高主动级别不扩大企业权限。</p></div>`:memoryPanel(c)}</div><footer>${B('全部确认','queue','','small')}<span>本地模拟 · 来源可核对</span></footer></aside>`;}
function memoryPanel(c){const m=c.state.settings.memory;return `<div class="of-section-heading"><h3>长期记忆 ${tag(c,'记忆演进')}</h3><button class="btn small" data-action="app:go" data-route="settings/memory">管理全部</button></div><p class="of-muted">偏好经确认才长期保存；项目资料不会自动变成个人记忆。</p><div class="of-memory-candidate"><small>待确认偏好 · 来自本次示例约定</small><h3>汇报先给结论，再列依据与待确认项</h3>${B('核对范围并记住','memory','','primary small')}</div>${m.items.map(x=>`<div class="of-memory"><div><strong>${E(x.title)}</strong>${pill(x.scope==='project'?'项目范围':'个人工作')}</div><p>${E(x.text)}</p><small>${E(x.source||'手动确认')}</small><button class="btn ghost small" data-action="work:memory-edit" data-id="${E(x.id)}">纠正</button><button class="btn ghost small" data-action="work:memory-delete" data-id="${E(x.id)}">删除</button></div>`).join('')}<p class="of-muted">任务内可查看实际采用的记忆快照；修改不会悄悄改写旧运行。</p>`;}

function commit(c){c.save();c.render();}
function launch(c,key,prompt,options={}){const fromAgent=c.ui.route.startsWith('agent/')?c.ui.route.slice(6):'';const a=agentBy(c,options.agentId||fromAgent||'personal');const project=options.project??(c.ui.route.startsWith('project/')?c.ui.route.slice(8):['proposal','builder'].includes(key)?c.state.projects.find(p=>p.id==='design')?.id||'':'');return c.startTask(prompt||SCENARIOS[key].prompt,{officeScenario:key,agentId:a?.id,agentName:a?.name,expert:a?.name,context:[...(c.state.homeContext||[])],...options,project});}
function roleOptions(c,current=''){return `<optgroup label="运行角色 · 本次任务">${[...new Set([current,...ROLES,'小悠 · Lead'].filter(r=>r&&!r.includes('企业专家')))].map(r=>`<option ${current===r?'selected':''}>${E(r)}</option>`).join('')}</optgroup><optgroup label="我的专家 · 企业已发布">${savedExperts(c.state).map(a=>{const value=a.name+' · 企业专家';return `<option ${current===value?'selected':''}>${E(value)}</option>`;}).join('')}</optgroup>`;}
function roleFields(c,role){const a=savedExperts(c.state).find(a=>role===a.name+' · 企业专家');return a?{agentType:'published',expertId:a.id,expertVersion:a.version}:{agentType:role.includes('Lead')?'lead':role.includes('独立验收')?'verifier':'temporary',expertId:null,expertVersion:null};}
function stepModal(c,t,id){const o=t.office,s=o.steps.find(s=>s.id===id);if(!s)return;const readonly=o.phase==='running';c.modal('步骤详情与分工',`<form data-form="office:step"><input type="hidden" name="task" value="${t.id}"><input type="hidden" name="id" value="${s.id}"><label class="field">步骤目标<input name="title" value="${E(s.title)}" required ${readonly?'disabled':''}></label><label class="field">负责角色<select name="role" ${readonly?'disabled':''}>${roleOptions(c,s.role)}</select></label><label class="field">交付物<input name="output" value="${E(s.output)}" required ${readonly?'disabled':''}></label><fieldset class="of-dep-fields"><legend>前置依赖</legend>${o.steps.filter(x=>x.id!==id).map(x=>`<label><input type="checkbox" name="deps" value="${x.id}" ${s.deps.includes(x.id)?'checked':''} ${readonly?'disabled':''}>${E(x.title)}</label>`).join('')}</fieldset><div class="notice">来源：${s.expertId?'我的专家 · 已发布定义与版本':s.id==='check'?'独立验收角色':'主 Agent 为本次任务创建的运行角色'}；角色的权限不能超过当前任务。依赖与角色变更生成新计划版本。</div>${s.optional?B('移除这个可选步骤','remove-step',`data-id="${s.id}"`,'danger ghost'):''}${s.status==='complete'?`<p>已完成：${E(s.output)}。成果与操作见右侧文件和运行回放。</p>`:''}<div class="form-actions"><button type="button" class="btn" data-action="app:close-modal">返回现场</button>${readonly?B('暂停后修改','pause','','primary'):'<button class="btn primary">保存计划变更</button>'}</div></form>`,{drawer:true});}
function confirmation(c,t){const a=t.office.approval;if(!a)return c.toast('先完成独立验收与 Lead 自核');c.modal('确认这一次操作',`<div class="of-confirm-heading">${icon('shield',26)}<div><strong>${E(a.action)}</strong><p>${E(a.target)}</p></div>${pill({pending:'待确认',approved:'已批准',rejected:'已拒绝',invalid:'已失效',executed:'已执行'}[a.status],'orange')}</div><dl class="detail-list"><dt>操作对象</dt><dd>${E(a.target)}</dd><dt>执行身份</dt><dd>我 · 当前任务所用业务专家</dd><dt>影响范围</dt><dd>仅上列示例对象，不扩展到其他文档、订单或成员</dd><dt>批准范围</dt><dd>${E(a.scope)}</dd><dt>绑定版本</dt><dd>计划 v${a.planVersion}；${a.versions.map(f=>E(f.name)+' v'+f.version).join('；')}</dd><dt>企业策略</dt><dd>模拟策略通过 · 凭据不下发给角色 · 敏感操作仍需人工批准</dd></dl><h3 class="of-modal-title">即将写入的内容</h3><div class="of-content-preview">${report(t)?.content.pages.map(p=>`<strong>${E(p.heading)}</strong><p>${p.paragraphs.map(E).join('<br>')}</p>`).join('')||'暂无内容'}</div><p class="of-muted">只记录本地模拟结果，不修改真实飞书、订单或团队应用。</p><div class="form-actions">${B('拒绝并停止','reject',`data-id="${a.id}"`,'danger ghost')}${B('返回修改','edit-report','','small')}${a.status==='pending'?B('批准本次操作','approve',`data-id="${a.id}"`,'primary'):''}</div>`,{wide:true});}
function queue(c){const list=tasks(c).filter(t=>t.office.approval);c.modal('统一确认中心',`<p class="of-muted">任务内与全局引用同一确认记录。批准只对当前内容与对象有效。</p>${list.length?list.map(t=>`<button class="of-task-row" data-action="office:queue-task" data-id="${t.id}"><span>${icon('shield',20)}</span><span class="of-task-text"><strong>${E(t.office.approval.action)}</strong><small>${E(t.title)} · ${E(t.office.approval.target)}</small></span>${pill(({pending:'待确认',approved:'已批准',rejected:'已拒绝',invalid:'已失效',executed:'已执行'})[t.office.approval.status],'orange')}</button>`).join(''):'<div class="of-empty-inline">还没有待确认操作。完成一个任务的验收后会出现在这里。</div>'}`,{wide:true});}
function context(c,t){const o=t.office;c.modal('本次上下文、记忆与执行边界',`<div class="of-context-summary">${pill(`计划 v${o.planVersion}`,'blue')}${pill('当前任务权限范围')}${pill(agentBy(c,o.agentId)?.version||'内置')}</div><h3>资料与口径</h3><p>${E(o.scope)}</p>${o.sources.map((s,i)=>`<button class="of-task-row" data-action="office:source" data-index="${i}">${icon('book',18)}<strong>${E(s.name)}</strong><small>${E(s.version)} · ${s.available?'就绪':'未就绪'}</small></button>`).join('')}<h3>实际采用的记忆</h3>${t.memorySnapshot?.length?t.memorySnapshot.map(m=>`<div class="of-memory"><strong>${E(m.title||m.text)}</strong><p>${E(m.text)}</p><small>${m.scope==='project'?'仅本项目':'个人工作'} · v${m.version||1}</small></div>`).join(''):'<p class="of-muted">本次没有采用长期记忆。</p>'}<h3>跨应用连接</h3><div class="of-check-row">${icon(o.phase==='blocked'?'alert':'checkCircle',18)}<div><strong>业务查询连接 · ${o.phase==='blocked'?'失效':'示例就绪'}</strong><p>只读查询；调用留痕关联当前 Task／Run／Step</p></div></div><div class="of-check-row">${icon('shield',18)}<div><strong>飞书文档／团队发布 · 按次人审</strong><p>凭据托管 · 对象与内容绑定 · 权限取交集</p></div></div><p class="notice">以上连接状态为本地模拟。此处展示主流程如何消费企业网关与权限能力。</p>`,{drawer:true});}
function editReport(c,t){const f=report(t);if(!f)return c.toast('执行到撰稿后，报告会出现在这里');c.modal('修改报告局部',`<form data-form="office:report"><input type="hidden" name="task" value="${t.id}"><input type="hidden" name="file" value="${f.id}"><input type="hidden" name="version" value="${f.version}"><p class="of-muted">当前 ${E(f.name)} v${f.version}；保存后重新验收，旧的待确认／批准失效。</p><label class="field">结论段落<textarea name="text" rows="6" required>${E(f.content.pages[0].paragraphs[0])}</textarea></label><div class="form-actions"><button type="button" class="btn" data-action="app:close-modal">取消</button><button class="btn primary">保存为新版本</button></div></form>`);}
export function handleOffice(action,el,c){initOffice(c.state);const t=current(c),o=t?.office,id=el.dataset.id;
  if(action==='app:duplicate-task'&&taskBy(c,id)?.office){const original=taskBy(c,id);const copyId=launch(c,original.office.scenario,original.prompt,{agentId:original.office.agentId,project:original.project});taskBy(c,copyId).title=original.title+' · 副本';c.save();return true;}
  if(action==='app:go'){c.ui.officePersonalOpen=false;return false;}
  if(action==='per:open'){c.ui.officePersonalOpen=true;c.ui.personalOpen=false;commit(c);return true;}
  if(action==='catalog:summon'){const x=c.state.catalog.experts.find(x=>x.id===id);if(x){let a=c.state.office.agents.find(a=>a.catalogId===id);if(!a){a={id:uid('agent'),catalogId:id,name:x.name,description:x.description||x.desc,source:x.source||'企业专家',version:'v1',pinned:true,icon:'expert'};c.state.office.agents.push(a);}a.pinned=true;c.save();c.closeModal();c.toast('已固定到左侧，可以在同一段对话里继续');c.go('agent/'+a.id);}return true;}
  if(!action.startsWith('office:'))return false;const a=action.slice(7);if(['template','use-template','publish-template','confirm-publish','templates'].includes(a)){c.go('agent/personal');return true;}
  if(a==='home-filter'){c.ui.homeWorkFilter=id;c.render();return true;}
  if(a==='home-methods'){c.popover(el,renderSkillEntry(c,{list:true}),250);return true;}
  if(a==='home-examples'){c.popover(el,Object.entries(SCENARIOS).map(([key,s])=>`<button data-action="office:scenario" data-id="${key}">${icon(s.icon,16)}<span>${E(s.name)}<small>${{review:'从资料到经营复盘',reconcile:'核对、异常与恢复',proposal:'项目协作与交接',builder:'创建助手与试用发布'}[key]}</small></span></button>`).join(''),220);return true;}
  if(a==='marks'){c.state.office.reviewMarks=!c.state.office.reviewMarks;commit(c);return true;}
  if(a==='compare'){c.modal('本次改动 · 与原版对照',`<p class="of-muted">本轮调整：同一专家支持独立的新建对话，历史对话可搜索、切换和重命名。每条对话分别保存消息、草稿、资料与任务，任务入口返回所属对话；旧会话完整保留。左侧专家与最近工作仍各显示三条，首页仍为两个模块。</p><div class="of-compare-grid"><div><small>原有交互</small><h3>召唤专家 → 新开对话</h3><p>固定四段进度；计划模式为预设三步；权限仅有文字选项。</p></div><div><small>本次演进</small><h3>固定 Agent → 持续对话</h3><p>召唤后固定到左侧；普通问答、工作补充与成果讨论保留在同一段对话。</p></div><div><small>原有交互</small><h3>对话与右侧文件</h3><p>消息流承载运行，缺少操作级确认与统一回放。</p></div><div><small>本次演进</small><h3>同一现场推进到交付</h3><p>计划—执行—确认—回放；异常恢复、版本失效、人审与回执。</p></div><div><small>原有能力</small><h3>规则建议与记忆</h3><p>提醒暂停任务、关注本地成果变化、记住偏好。</p></div><div><small>本次演进</small><h3>个人办公入口</h3><p>跨项目概览、固定专家、主动性 L0—L3、敏感操作边界。</p></div></div><div class="form-actions"><a class="btn" href="../versions/compact-home-v13/#agent/bi" target="_blank" rel="noopener">对照上一版</a><a class="btn" href="../versions/conversation-v3/#agent/bi" target="_blank" rel="noopener">对照上版持续对话</a><a class="btn" href="../versions/worksite-v2/#home" target="_blank" rel="noopener">对照上版工作台</a><a class="btn" href="../versions/branding-v1/#home" target="_blank" rel="noopener">打开原版交互对照</a>${B('体验经营复盘','scenario','data-id="review"','primary')}</div>`,{wide:true});return true;}
  if(a==='reset'){c.modal('重置本轮体验？',`<p>只清除本轮新增的演示任务与小悠约定；原有任务、记忆和项目保留。</p><div class="form-actions"><button class="btn" data-action="app:close-modal">取消</button>${B('确认重置本轮体验','confirm-reset','','danger')}</div>`);return true;}
  if(a==='confirm-reset'){c.state.tasks=c.state.tasks.filter(t=>!t.office);delete c.state.office;initOffice(c.state);c.ui.officePersonalOpen=false;c.save();c.go('home');return true;}
  if(a==='scenario'){c.ui.officePersonalOpen=false;launch(c,id);return true;}
  if(a==='home'||a==='agents'){c.ui.officePersonalOpen=false;c.go(a==='home'?'home':'experts');return true;}
  if(a==='pin'){const ag=agentBy(c,id);if(ag)ag.pinned=!ag.pinned;commit(c);return true;}
  if(a==='agent-detail'){const ag=agentBy(c,id);c.modal(ag.name,`<p>${E(ag.description)}</p><dl class="detail-list"><dt>来源与版本</dt><dd>${E(ag.source)} · ${E(ag.version)}</dd><dt>维护团队</dt><dd>示例业务团队 · 林沐／陈语</dd><dt>工作方法</dt><dd>明确口径，按需分工，保留来源，独立验收后交付。</dd><dt>权限</dt><dd>实际运行取用户、项目、工具与企业策略的交集。</dd></dl><p class="notice">点击左侧 Agent 回到持续对话；单次任务内部的小队角色不增加新的侧栏对话。</p>`);return true;}
  if(a==='discover'){c.modal('发现并固定专家',`<div class="picker-list">${c.state.catalog.experts.map(x=>`<button data-action="catalog:summon" data-id="${x.id}">${icon('expert',22)}<span><strong>${E(x.name)}</strong><small>召唤并固定到左侧 · 持续对话</small></span>${icon('pin',17)}</button>`).join('')}</div>`);return true;}
  if(a==='personal'){c.ui.officePersonalOpen=true;c.ui.personalOpen=false;commit(c);return true;}
  if(a==='close-personal'){c.ui.officePersonalOpen=false;commit(c);return true;}
  if(a==='personal-tab'){c.ui.officePersonalTab=id;commit(c);return true;}
  if(a==='level'){const level=+el.dataset.level;if(level===3){c.modal('按约定推进 · 白名单',`<p>只允许：本地整理、更新任务标签、归档演示草稿。范围仅为你选择的示例任务。</p><p>预算：每次最多 6 个步骤；约定仅本次演示有效。外部发送、业务写回、发布与权限变化仍需人审。</p><div class="form-actions"><button class="btn" data-action="app:close-modal">取消</button>${B('保存这份工作约定','confirm-level','','primary')}</div>`);}else{c.state.office.level=level;commit(c);}return true;}
  if(a==='confirm-level'){c.state.office.level=3;c.closeModal();commit(c);return true;}
  if(a==='quiet'){c.state.office.quiet=!c.state.office.quiet;c.toast(c.state.office.quiet?'已暂停主动提醒，已交办工作仍保留':'已恢复主动提醒');commit(c);return true;}
  if(a==='dismiss'){c.state.office.dismissed.push('prepare');commit(c);return true;}
  if(a==='dismiss-signal'){c.state.office.dismissed.push(id);commit(c);return true;}
  if(a==='prepare'){c.state.office.prepared=true;c.state.office.dismissed.push('prepare');c.ui.officePersonalOpen=false;const id=launch(c,'review','为示例经营复盘准备计划和草稿，任何外部写回都先让我确认。');const prepared=taskBy(c,id);startRun(prepared);prepared.office.view='execute';event(prepared,'小悠按约定先准备','本次由你交办，只推进允许的只读与草稿步骤；外部动作仍需人审。','proactive');c.save();return true;}
  if(a==='follow'){if(!t)return c.toast('先打开一件任务，再选择关注'),true;if(!c.state.office.follows.includes(t.id))c.state.office.follows.push(t.id);c.state.office.followVersions||={};c.state.office.followVersions[t.id]=Object.fromEntries(t.files.map(f=>[f.id,f.version]));c.toast('已关注此任务与成果版本');commit(c);return true;}
  if(a==='unfollow'){c.state.office.follows=c.state.office.follows.filter(x=>x!==id);commit(c);return true;}
  if(a==='memory'){c.modal('确认这条长期记忆',`<form data-form="office:memory"><label class="field">记住什么<textarea name="text" rows="3" required>汇报先给结论，再列依据与待确认项。</textarea></label><label class="field">适用范围<select name="scope"><option value="global">我的个人工作</option>${c.state.projects.map(p=>`<option value="${p.id}">仅项目：${E(p.name)}</option>`).join('')}</select></label><p class="of-muted">来源：你在本次示例工作约定中主动确认。保存后，新任务可查看采用记录。</p><div class="form-actions"><button type="button" class="btn" data-action="app:close-modal">只用本次</button><button class="btn primary">确认记住</button></div></form>`);return true;}
  if(a==='queue'){queue(c);return true;}
  if(a==='source-task'||a==='queue-task'){const target=taskBy(c,id);if(target){c.ui.officePersonalOpen=false;if(a==='queue-task')target.office.view='approval';c.go('chat/'+id);}else c.toast('原任务已不存在');return true;}
  if(a==='team'){c.modal('团队 Agent · 共同维护',`<h3>产品方案专家 · 已发布 v1.4</h3><p>维护者：林沐、陈语 · 发布者：周一</p><div class="of-check-row">${icon('expert',20)}<div><strong>同一个 Agent，多人共同维护</strong><p>工作说明、知识、工具和验收标准按版本协作；使用者消费已发布版本。</p></div></div><p>候选改动：异常复核面板与独立验收样例。完整构建器与企业角色接入另行交付，当前演示主流程衔接。</p>${B('开始助手建设样例','scenario','data-id="builder"','primary')}`);return true;}
  if(a==='project-sources'){c.modal('项目资料与已确认决定',`<p>仅使用本项目获准的资料。这里展示流程图 v2、访谈摘录样例与“业务写回保留人工确认”的已确认决定。</p><p>切换项目不会携带其他项目正文；全局小悠只汇总获准的状态与必要摘要。</p>`);return true;}
  if(!o){c.toast('请先打开本轮工作任务');return true;}
  if(a==='eval'){c.modal('复核助手 · 评测样例',`<p class="of-muted">本地规则样例，不代表真实模型评测。</p>${[['正常订单','金额与状态一致，保留记录，不更新业务系统'],['金额差异','指出具体差额，等待人工确认'],['连接无权限','阻断查询，说明缺口，不伪造结果']].map(([n,d])=>`<div class="of-check-row">${icon('checkCircle',18)}<div><strong>${n}</strong><p>${d}</p></div>${pill('预期行为')}</div>`).join('')}<p>当前候选绑定计划 v${o.planVersion} 与成果版本；运行中的旧版本不会被覆盖。</p>`);}
  else if(a==='builder-feedback'){c.modal('同事试用与反馈',`<form data-form="office:builder-feedback"><input type="hidden" name="task" value="${t.id}"><p>陈语 · 示例同事 · 试用异常订单复核候选 v1</p><label class="field">反馈<textarea name="note" rows="4" required>异常卡片应补充两个来源的更新时间，便于判断状态冲突。</textarea></label><p class="notice">反馈回到同一建设任务，记录为候选改进，不自动覆盖已发布版本。</p><div class="form-actions"><button class="btn primary">提交试用反馈</button></div></form>`);}
  else if(a==='view'){o.view=el.dataset.view;commit(c);}
  else if(a==='step')stepModal(c,t,id);
  else if(a==='add-step'){if(o.phase==='running')return c.toast('请先暂停运行，再增补步骤'),true;c.modal('按需增补专家步骤',`<form data-form="office:add-step"><input type="hidden" name="task" value="${t.id}"><label class="field">检查目标<input name="title" value="补充业务风险检查" required></label><label class="field">专家或企业方法<select name="role">${roleOptions(c)}</select></label><label class="field">交付物<input name="output" value="风险清单与待确认项" required></label><label class="field">安排在谁之后<select name="after">${o.steps.filter(s=>!['check','lead','deliver'].includes(s.id)).map(s=>`<option value="${s.id}" ${s.id==='write'?'selected':''}>${E(s.title)}</option>`).join('')}</select></label><p class="notice">新角色使用本任务的执行现场与权限，独立验收会等待它的交付物。临时角色归属本次任务；企业专家引用已发布版本。</p><div class="form-actions"><button class="btn primary">加入小队并更新计划</button></div></form>`);}
  else if(a==='remove-step'){const result=removeStep(t,id);if(result.error)c.toast(result.error);else c.closeModal();commit(c);}
  else if(a==='move'){const index=o.steps.findIndex(s=>s.id===id),target=o.steps[index+(+el.dataset.direction)];if(target){const result=reorder(t,id,target.id);if(result.error)c.toast(result.error);commit(c);}}
  else if(a==='start'){if(startRun(t)){o.view='execute';c.closeModal();commit(c);}}
  else if(a==='pause'){pause(t);c.closeModal();commit(c);}
  else if(a==='advance'){if(!advance(t))c.toast('请先采用计划；遇到阻塞时先处理提示');if(o.phase==='ready')o.view='approval';commit(c);}
  else if(a==='fail'){if(['plan','running','paused'].includes(o.phase)){const step=o.steps.find(s=>s.id==='data');o.failureArmed=true;if(step.status==='complete')step.status='failed';if(o.phase==='running'||step.status==='failed'){o.phase='blocked';o.failureUsed=true;step.status='failed';event(t,'模拟连接失败','已有成果保留；恢复后从数据步骤继续。','failure');}c.toast('已模拟数据连接异常');commit(c);}else c.toast('请在计划或执行阶段模拟连接失败');}
  else if(a==='recover'){recover(t);commit(c);}
  else if(a==='repair'){repair(t);o.view='execute';commit(c);}
  else if(a==='context')context(c,t);
  else if(a==='source'){const s=o.sources[+el.dataset.index];if(s)c.modal('核对资料来源',`<h3>${E(s.name)}</h3><p>来源 ID：${E(s.id)} · 版本：${E(s.version)}</p><p>范围：${E(o.scope)}</p><p>示例事实：${o.scenario==='review'?'本周 1094 笔、上周 1000 笔，变化 9.4%；含税收入同口径增长 9.4%。':'本文档／记录为当前场景的合成输入；不连接企业资料。'}</p><p class="notice">用于本次运行，不代表拥有其他项目或来源的读取权限。</p>`);}
  else if(a==='approval')confirmation(c,t);
  else if(a==='approve'){if(decide(t,'approve',id)){c.closeModal();o.view='approval';commit(c);}else{c.toast('确认已处理或版本已变化，请重新核对');commit(c);}}
  else if(a==='reject'){if(decide(t,'reject',id)){c.closeModal();o.view='approval';commit(c);}else c.toast('此确认已处理或失效');}
  else if(a==='execute'){if(execute(t,id)){o.view='approval';commit(c);}else{c.toast('未执行：批准无效、已使用或内容已变化');commit(c);}}
  else if(a==='edit-report')editReport(c,t);
  else if(a==='revise-delivery'){c.modal('调整交付范围',`<form data-form="office:delivery"><input type="hidden" name="task" value="${t.id}"><label class="field">交付动作<input name="action" value="${E(o.delivery)}" required></label><label class="field">具体对象<input name="target" value="${E(o.target)}" required></label><p class="notice">改变对象或内容将使原确认失效；拒绝后的动作不会自动恢复。</p><div class="form-actions"><button class="btn primary">保存并重新提交确认</button></div></form>`);}
  else if(a==='automation'){c.modal('设为持续助理',`<form data-form="office:automation"><input type="hidden" name="task" value="${t.id}"><label class="field">触发方式<select name="trigger"><option value="weekly">每周五 09:00</option><option value="document">指定示例飞书文档变更</option><option value="mail">指定示例邮件信号</option></select></label><label class="field">运行环境<select name="environment"><option>企业云端 · 模拟</option><option>本机 · 需保持在线</option></select></label><label class="field">主动性<select name="level"><option value="2">先帮我准备 · 敏感动作仍人审</option><option value="1">只提醒我有变化</option></select></label><p class="notice">保存为本地配置，不启动真实后台调度。执行结果与送达结果分别记录。</p><div class="form-actions"><button class="btn primary">保存持续助理</button></div></form>`);}
  else if(a==='handoff'){c.modal('交接这项工作',`<form data-form="office:handoff"><input type="hidden" name="task" value="${t.id}"><label class="field">接收同事<select name="owner"><option>陈语 · 示例同事</option><option>林沐 · 示例同事</option></select></label><label class="field">交接说明<textarea name="note" rows="3" required>已完成资料核对与方案草稿，请继续评审并补充建议。</textarea></label><p class="notice">交接包含目标、计划、成果、来源与待办；不继承凭据或原审批资格。无权限资料需接收人重新申请。</p><div class="form-actions"><button class="btn primary">模拟接收并完成交接</button></div></form>`);}
  else if(a==='colleague'){c.modal('同事补充要求',`<form data-form="office:colleague"><input type="hidden" name="task" value="${t.id}"><label class="field">陈语 · 示例同事<textarea name="note" rows="4" required>请补充异常处理路径，并区分已确认决定和待验证假设。</textarea></label><p class="of-muted">补充将进入任务记录并形成待采纳计划变更，不直接成为已确认项目决定。</p><div class="form-actions"><button class="btn primary">加入工作并调整计划</button></div></form>`);}
  else if(a==='task-menu'){c.modal('这项工作',`<p>当前负责人：${E(o.owner)} · ${E(PHASES[o.phase])}</p><div class="picker-list">${B('交给小悠持续关注','follow')}${B('交接给同事','handoff')}${B('查看上下文与企业边界','context')}${B('取消后续执行','cancel')}</div>`);}
  else if(a==='cancel'){o.phase='cancelled';invalidateApproval(t,'任务已取消');event(t,'取消后续执行','已完成成果保留；已发生的交付不伪装撤回。','control');c.closeModal();commit(c);}
  return true;
}
export function submitOffice(name,form,c){if(!name.startsWith('office:'))return false;const v=Object.fromEntries(new FormData(form)),t=v.task?taskBy(c,v.task):current(c),o=t?.office;const a=name.slice(7);if(['template','use-template','publish-template','confirm-publish','templates'].includes(a))return true;
  if(a==='start'){const prompt=(v.prompt||'').trim();if(!prompt)return c.toast('先写下工作目标'),true;launch(c,detectScenario(prompt),prompt,{agentId:v.agent||'personal',project:v.project||''});c.state.homeDraft='';c.state.homeContext=[];c.save();return true;}
  if(a==='memory'){const text=(v.text||'').trim();if(!text)return true;if(c.state.settings.memory.items.some(m=>m.text===text&&m.projectId===(v.scope==='global'?'':v.scope))){c.toast('这条偏好已保存，没有重复添加');return true;}c.state.settings.memory.items.push({id:uid('memory'),title:text.slice(0,35),text,scope:v.scope==='global'?'global':'project',projectId:v.scope==='global'?'':v.scope,source:'你在小悠工作约定中确认 · 合成示例',version:1,createdAt:Date.now()});c.closeModal();commit(c);return true;}
  if(!o)return true;
  if(a==='add-step'){const result=addStep(t,{title:v.title.trim(),role:v.role,...roleFields(c,v.role),output:v.output.trim(),after:v.after});if(result.error)return c.toast(result.error),true;c.closeModal();commit(c);}
  else if(a==='step'){const result=updateStep(t,v.id,{title:v.title.trim(),role:v.role,...roleFields(c,v.role),output:v.output.trim(),deps:new FormData(form).getAll('deps')});if(result.error)return c.toast(result.error),true;c.closeModal();commit(c);}
  else if(a==='report'){const f=t.files.find(f=>f.id===v.file);if(!f||f.version!==+v.version)return c.toast('成果版本已变化，请重新选择'),true;const before=f.content.pages[0].paragraphs[0],after=v.text.trim();if(before===after)return c.toast('内容没有变化'),true;t.versions.push({id:uid('version'),fileId:f.id,version:f.version,content:structuredClone(f.content),at:new Date().toISOString()});const from=f.version++;f.content.pages[0].paragraphs[0]=after;t.changes.push({id:uid('change'),fileId:f.id,fileName:f.name,target:'pages.0.paragraphs.0',before,after,fromVersion:from,toVersion:f.version,at:new Date().toISOString(),comment:'用户修改结论'});syncArtifacts(t);event(t,'用户修改报告局部',`v${from} → v${f.version}；版本变化使旧确认失效。`,'version');o.view='execute';c.closeModal();commit(c);}
  else if(a==='delivery'){const changed=o.target!==v.target.trim()||o.delivery!==v.action.trim();if(changed||o.phase==='rejected'){invalidateApproval(t,'交付对象或动作已修改');o.target=v.target.trim();o.delivery=v.action.trim();event(t,'调整交付方案',`${o.delivery} → ${o.target}`,'plan');if(o.quality==='passed')createApproval(t);o.view='approval';}c.closeModal();commit(c);}
  else if(a==='automation'){const id=uid('schedule');c.state.workspace.schedules.push({id,name:t.title+' · 持续助理',prompt:t.prompt,type:'periodic',frequency:'weekly',weekday:'5',time:'09:00',model:'自动',permission:'approve',notify:'always',context:'continue',enabled:true,history:[],lastTaskId:t.id,office:{trigger:v.trigger,environment:v.environment,level:+v.level,sourceTaskId:t.id},parseNote:'本地模拟持续助理配置，外部事件和后台调度未连接。'});event(t,'保存持续助理',`${v.trigger} · ${v.environment} · 敏感操作仍人审。`,'automation');c.closeModal();c.toast('持续助理已保存，可在任务中心查看与试跑');commit(c);}
  else if(a==='builder-feedback'){o.feedback||=[];o.feedback.push({from:'陈语 · 示例同事',text:v.note,at:Date.now()});event(t,'同事试用反馈',v.note+'；已记录为候选改进。','feedback');o.view='replay';c.closeModal();commit(c);}
  else if(a==='handoff'){o.owner=v.owner;o.handoff={to:v.owner,note:v.note,at:Date.now()};invalidateApproval(t,'负责人已变化，接收者需重新核对权限');if(o.approval?.status==='invalid'&&o.quality==='passed')createApproval(t);event(t,'同事接收任务交接',`${v.owner}：${v.note}；未转移凭据或审批资格。`,'handoff');c.closeModal();c.toast('已模拟交接，同一任务与成果保留');commit(c);}
  else if(a==='colleague'){if(o.phase==='running')pause(t);const result=updateStep(t,'write',{output:'方案草稿 + 异常处理 + 决定与假设分列'});if(result.error)return c.toast(result.error),true;o.requirements||=[];o.requirements.push(v.note);event(t,'陈语补充工作要求',v.note,'collaboration');t.messages.push({role:'user',text:'陈语（示例同事）：'+v.note,time:Date.now()});o.view='plan';c.closeModal();commit(c);}
  else if(a==='message'){const text=(v.message||'').trim();if(!text&&!t.annotations.length)return true;if(t.annotations.length){if(!report(t))return c.toast('成果生成后再提交批注'),true;const changes=applyAnnotations(t);syncArtifacts(t);event(t,'提交元素批注',`应用 ${changes.length} 处修改；冲突批注保留，按最新版本重新核对。`,'version');}if(text){t.messages.push({role:'user',text,time:Date.now()});if(o.phase==='running')pause(t);o.requirements||=[];o.requirements.push(text);updateStep(t,'write',{output:'交付草稿 · 已纳入补充要求'});o.view='plan';event(t,'收到补充要求并更新计划',text+'；后续草稿附带此要求，重新采用计划后继续。','input');}o.draft='';c.save();c.render();}
  return true;
}
export function inputOffice(el,c){if(el.dataset.live==='office:home'){c.state.homeDraft=el.value;c.save();return true;}if(el.dataset.live==='office:task'){const t=current(c);if(t?.office)t.office.draft=el.value;c.save();return true;}return false;}
export function tickOffice(c){if(c.ui.modal||c.isInteracting?.())return;const active=document.activeElement;if(active?.matches('input,textarea,select,[contenteditable="true"]'))return;let changed=false;for(const t of tasks(c)){if(t.office.phase==='running'&&Date.now()-(t.office.lastTick||0)>4500){changed=advance(t)||changed;if(t.office.phase==='ready')t.office.view='approval';}}if(changed)commit(c);}
export function initOfficeInteractions(c){let pointerDrag=null;document.addEventListener('pointerdown',e=>{const grip=e.target.closest('[data-office-drag-handle]'),node=grip?.closest('[data-office-step]');if(!node||e.button!==0)return;const t=taskBy(c,node.dataset.task);if(!t||t.office.phase==='running')return;e.preventDefault();pointerDrag={task:t.id,id:node.dataset.officeStep,x:e.clientX,y:e.clientY,active:false};});document.addEventListener('pointermove',e=>{if(!pointerDrag)return;if(Math.hypot(e.clientX-pointerDrag.x,e.clientY-pointerDrag.y)>8){pointerDrag.active=true;document.querySelector(`[data-office-step="${pointerDrag.id}"]`)?.classList.add('of-dragging');}if(pointerDrag.active){document.querySelectorAll('.of-drop-target').forEach(n=>n.classList.remove('of-drop-target'));const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-office-step]');if(target&&target.dataset.officeStep!==pointerDrag.id)target.classList.add('of-drop-target');}});document.addEventListener('pointerup',e=>{if(!pointerDrag)return;const held=pointerDrag;pointerDrag=null;document.querySelectorAll('.of-dragging,.of-drop-target').forEach(n=>n.classList.remove('of-dragging','of-drop-target'));if(!held.active)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-office-step]'),t=taskBy(c,held.task);if(target&&t&&target.dataset.task===t.id){const result=reorder(t,held.id,target.dataset.officeStep);if(result.error)c.toast(result.error);commit(c);}});document.addEventListener('pointercancel',()=>{pointerDrag=null;document.querySelectorAll('.of-dragging,.of-drop-target').forEach(n=>n.classList.remove('of-dragging','of-drop-target'));});let dragged=null;document.addEventListener('dragstart',e=>{const node=e.target.closest('[data-office-step]');if(!node)return;dragged={task:node.dataset.task,id:node.dataset.officeStep};e.dataTransfer.setData('text/plain',node.dataset.officeStep);e.dataTransfer.effectAllowed='move';node.classList.add('of-dragging');});document.addEventListener('dragover',e=>{if(dragged&&e.target.closest('[data-office-step]')){e.preventDefault();e.dataTransfer.dropEffect='move';}});document.addEventListener('drop',e=>{const target=e.target.closest('[data-office-step]');if(!dragged||!target)return;e.preventDefault();const task=taskBy(c,dragged.task);if(task&&target.dataset.task===dragged.task){const result=reorder(task,dragged.id,target.dataset.officeStep);if(result.error)c.toast(result.error);commit(c);}dragged=null;});document.addEventListener('dragend',()=>{dragged=null;document.querySelectorAll('.of-dragging').forEach(n=>n.classList.remove('of-dragging'));});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&c.ui.officePersonalOpen){c.ui.officePersonalOpen=false;c.render();}if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&['office-prompt','office-task-input'].includes(e.target.id)){e.preventDefault();e.target.closest('form')?.requestSubmit();}});}

export {board as renderSquadPlan, execution as renderExecutionPanel, rubric as renderQualityPanel, approvalCard as renderApprovalPanel, replay as renderReplayPanel};
